// Gridrunner ships its own 64-glyph character set at $8E00 (copied to $2000).
// No built-in encoding applies: $30 is the letter O *and* the digit 0, $01 is
// a zapper, and $C0-$FF do not occur. The map below was read off the glyph
// bitmaps themselves - render $8E00 as char:8 and the letters are legible.
const HIGH = " GRIUDNEABFHJMPSO123456789TV()L|";
const LOW = {
  0x00: "+", 0x01: "[", 0x02: "^",
  0x03: "/", 0x04: "/", 0x05: "/", 0x06: "/",
  0x07: "A", 0x08: "!", 0x09: "!", 0x0a: "v",
  0x0b: ">", 0x0c: "<",
  0x0d: ".", 0x0e: "o", 0x0f: "O", 0x10: "0", 0x11: "@", 0x12: "*",
  0x13: "D", 0x14: "D", 0x15: "D",
  0x16: "'", 0x17: "'", 0x18: "'",
  0x19: "P", 0x1a: "L", 0x1b: "Y", 0x1c: "Y", 0x1d: "H", 0x1e: "I", 0x1f: "?",
};
const out = [];
let line = "";
for (const b of bytes) {
  if (b === 0x3c) { line += "(c"; continue; }
  if (b >= 0x20 && b <= 0x3f) { line += HIGH[b - 0x20]; continue; }
  line += LOW[b] !== undefined ? LOW[b] : "?";
}
const width = (params && params.width) || 40;
for (let i = 0; i < line.length; i += width) out.push(line.slice(i, i + width));
return { kind: "text", lines: out.length ? out : [""] };

// Gridrunner ships its own 64-glyph character set at $8E00 (copied to $2000 and
// selected by the $18 written to $D018). No built-in encoding applies, so every
// string in this program is unreadable without this map. It was read off the
// glyph bitmaps: render $8E00 as char:8 and the letters are legible.
//
// Only the letters the game's own text needs exist: A B D E F G H I J L M N O
// P R S T U V Y. There is no C, K, Q, W, X or Z anywhere in the set.
// $30 is a single glyph doing duty as both the letter O and the digit 0, which
// is why "PRESS FIRE TO BEGIN" and a seven-digit score share one byte value.
// $3C and $3D are the two halves of one copyright symbol.
const HIGH = " GRUIDNEABFHJMPSO123456789TV()L|";
const LOW = {
  0x00: "+", 0x01: "[", 0x02: "^",
  0x03: "/", 0x04: "/", 0x05: "/", 0x06: "/",
  0x07: "^", 0x08: "!", 0x09: "!", 0x0a: "v",
  0x0b: ">", 0x0c: "<",
  0x0d: ".", 0x0e: "o", 0x0f: "O", 0x10: "0", 0x11: "@", 0x12: "*",
  0x13: "D", 0x14: "D", 0x15: "D",
  0x16: "'", 0x17: "'", 0x18: "'",
  0x19: "P", 0x1a: "L", 0x1b: "Y", 0x1c: "Y", 0x1d: "H", 0x1e: "I", 0x1f: "?",
};
let line = "";
for (const b of bytes) {
  if (b === 0x3c) { line += "(c"; continue; }
  if (b >= 0x20 && b <= 0x3f) { line += HIGH[b - 0x20]; continue; }
  line += LOW[b] !== undefined ? LOW[b] : "?";
}
const width = (params && params.width) || 40;
const out = [];
for (let i = 0; i < line.length; i += width) out.push(line.slice(i, i + width));
return { kind: "text", lines: out.length ? out : [""] };

// C64 screen codes INCLUDING the reverse-video half. Codes $80-$FF are the
// reversed forms of $00-$7F, which re64's built-in "screen" encoding does not
// undo - it maps them through a graphics table instead, so the cartridge
// signature comes out as punctuation. Reversed characters are shown in
// brackets, which is what the CBM80 signature actually is: three reversed
// letters followed by two ordinary digits.
const B = "@abcdefghijklmnopqrstuvwxyz[\\]^_ !\"#$%&'()*+,-./0123456789:;<=>?";
const lines = [];
let out = "";
for (const b of bytes) {
  const rev = b >= 0x80;
  const c = b & 0x7f;
  const ch = c < B.length ? B[c].toUpperCase() : "?";
  out += rev ? "[" + ch + "]" : ch;
}
lines.push(out);
return { kind: "text", lines };

// C64 screen codes INCLUDING the reverse-video half. Codes $80-$FF are the
// reversed forms of $00-$7F; re64's built-in screen encoding does not undo that
// and maps them through a graphics table instead, so the cartridge signature
// comes out as punctuation. Reversed characters are shown in brackets here,
// which is exactly what CBM80 is: three reversed letters, then two digits.
const glyph = (c) => {
  if (c === 0) return '@';
  if (c >= 1 && c <= 26) return String.fromCharCode(64 + c);
  if (c >= 32 && c <= 63) return String.fromCharCode(c);
  return '.';
};
let out = '';
for (const b of bytes) {
  const ch = glyph(b & 0x7f);
  out += (b >= 0x80) ? ('[' + ch + ']') : ch;
}
return { kind: 'text', lines: [out] };

// PETSCII including the DUPLICATE LETTER RANGE. In the unshifted character set
// codes $C1-$DA render the same A-Z as $41-$5A; re64's built-in petscii encoding
// maps that upper range through a graphics table instead, so the standard C64
// cartridge signature comes out as punctuation rather than as CBM80.
const glyph = (b) => {
  if (b >= 0xc1 && b <= 0xda) return String.fromCharCode(b - 0xc0 + 64);
  if (b >= 0x41 && b <= 0x5a) return String.fromCharCode(b);
  if (b >= 0x20 && b <= 0x40) return String.fromCharCode(b);
  if (b >= 0x5b && b <= 0x5f) return String.fromCharCode(b);
  return '.';
};
let out = '';
for (const b of bytes) out += glyph(b);
return { kind: 'text', lines: [out] };
